const BATCH_SIZE = 15;

// 1. Los recursos SON los items
const resources = items.map(i => i.json);

if (!Array.isArray(resources) || resources.length === 0) {
  throw new Error("No se encontró un array de recursos");
}

console.log(`=== CREANDO BATCHES ===`);
console.log(`Total recursos: ${resources.length}`);
console.log(`Tamaño de batch: ${BATCH_SIZE}`);
console.log(`Batches esperados: ${Math.ceil(resources.length / BATCH_SIZE)}`);

// 2. JSON → CSV
function toCSV(arr) {
  const headers = [
    "ID", "titulo", "resumen", "tipo", 
    "categoria", "subcategoria", "palabrasClaves"
  ];

  const rows = arr.map(o => 
    headers
      .map(h => `"${(o[h] ?? "").toString().replace(/"/g, '""')}"`)
      .join(',')
  );

  return [headers.join(','), ...rows].join('\n');
}

// 3. Crear array de objetos output
const output = [];

for (let i = 0; i < resources.length; i += BATCH_SIZE) {
  const batch = resources.slice(i, i + BATCH_SIZE);
  const batchNumber = Math.floor(i / BATCH_SIZE) + 1;
  const batchCSV = toCSV(batch);

  const prompt = `Evalúa la pertinencia de ${batch.length} recursos educativos frente al syllabus.

## SYLLABUS DE LA MATERIA

**Nombre:** ${$('Edit Fields2').item.json.NOMBRE_MATERIA}
**Descripción:** ${$('Edit Fields2').item.json['DESCRIPCIÓN_GENERAL']}
**Competencias:** ${$('Edit Fields2').item.json.COMPETENCIAS}
**Temario:** ${$('Edit Fields2').item.json.TEMARIO}
**Palabras clave del curso:** ${$('Edit Fields2').item.json.PALABRAS_CLAVE_SYLLABUS}

## CRITERIOS DE EVALUACIÓN (califica 0-10 cada uno)

- **C1** (25%): Alineación con el objetivo general
- **C2** (25%): Cobertura de competencias del curso
- **C3** (20%): Correspondencia con el temario
- **C4** (15%): Coincidencia semántica de palabras clave
- **C5** (10%): Adecuación del tipo de recurso al aprendizaje práctico
- **C6** (5%): Aplicabilidad en contextos productivos reales

**Fórmula de pertinencia:**
Pertinencia = (C1×0.25) + (C2×0.25) + (C3×0.20) + (C4×0.15) + (C5×0.10) + (C6×0.05)

Redondea el resultado final a un número entero del 0 al 10.

## RECURSOS A EVALUAR (${batch.length} TOTAL)

⚠️ **CRÍTICO: Debes evaluar EXACTAMENTE ${batch.length} recursos. No omitas ninguno.**

\`\`\`csv
${batchCSV}
\`\`\`

## CONSTRUCCIÓN DE LA JUSTIFICACIÓN

Cada justificación debe tener 40-60 palabras e incluir:
1. Qué contenido específico aporta (conceptos, técnicas, herramientas)
2. Conexión explícita con tema/unidad/competencia del syllabus
3. Utilidad práctica en el contexto de la materia

## FORMATO DE RESPUESTA

Responde con un objeto JSON que contenga EXACTAMENTE ${batch.length} recursos evaluados.

**ESTRUCTURA EXACTA (no alteres nombres de llaves):**

{
  "resultados": [
    {
      "id": "ID_DEL_RECURSO",
      "titulo": "TÍTULO_DEL_RECURSO",
      "tipo": "TIPO_DEL_RECURSO",
      "palabraClave": "UNA_PALABRA_CLAVE",
      "justificacion": "Texto de 40-60 palabras",
      "pertinencia": 8,
      "criterios": {
        "c1": 9,
        "c2": 8,
        "c3": 7,
        "c4": 8,
        "c5": 9,
        "c6": 7
      }
    }
  ]
}

## VALIDACIÓN ANTES DE RESPONDER

✅ Cuenta que el array "resultados" tenga ${batch.length} elementos
✅ Verifica que cada objeto tenga las 7 llaves: id, titulo, tipo, palabraClave, justificacion, pertinencia, criterios
✅ Verifica que "criterios" tenga las 6 llaves: c1, c2, c3, c4, c5, c6
✅ Verifica que "pertinencia" sea un número entero entre 0 y 10
✅ Verifica que todos los c1-c6 sean números enteros entre 0 y 10
✅ Verifica que no haya comas mal colocadas en el JSON

## RESTRICCIONES OBLIGATORIAS

- Devuelve ÚNICAMENTE JSON válido RFC 8259
- NO incluyas markdown (\`\`\`json), texto explicativo, ni comentarios
- Comienza tu respuesta directamente con el carácter {
- NO incluyas NADA antes ni después del JSON
- Usa solo información del syllabus, no inventes datos
- Cada recurso debe evaluarse de forma independiente

**RECORDATORIO: Debes incluir exactamente ${batch.length} recursos evaluados.**`;

  // Envolver el objeto interno en un objeto con clave 'json' como n8n requiere
  output.push({
    json: {
      numero_ejecucion: $('Crypto').first().json.data,
      chatInput: prompt
    }
  });
}

// Retornar array de objetos envueltos en {json: ...}
return output;

// Tomamos el JSON completo (ya agregado)
const data = items[0].json;

// Obtenemos el nombre de la materia
let nombreMateria = $('Edit Fields2').first().json.NOMBRE_MATERIA;

// Normalizamos el nombre:
// - minúsculas
// - sin acentos
// - espacios a "_"
// - solo letras, números y "_"
const safeName = nombreMateria
  .toLowerCase()
  .normalize('NFD')                  // separa acentos
  .replace(/[\u0300-\u036f]/g, '')   // elimina acentos
  .replace(/\s+/g, '_')              // espacios → _
  .replace(/[^a-z0-9_]/g, '');       // limpia caracteres raros

// Convertimos el JSON a string
const jsonString = JSON.stringify(data, null, 2);

// Creamos el archivo binario
const buffer = Buffer.from(jsonString, 'utf8');

// Nombre final del archivo
const fileName = `${safeName}.json`;

return [
  {
    json: {
      filename: fileName
    },
    binary: {
      file: {
        data: buffer,
        mimeType: 'application/json',
        fileName
      }
    }
  }
];

// Datos fijos desde otro nodo
const nombre_materia = $('Edit Fields2').first().json.NOMBRE_MATERIA;
const descripcion_general = $('Edit Fields2').first().json["DESCRIPCIÓN_GENERAL"];
const competencias = $('Edit Fields2').first().json.COMPETENCIAS;
const temario = $('Edit Fields2').first().json.TEMARIO;
const palabras_clave = $('Edit Fields2').first().json.PALABRAS_CLAVE_SYLLABUS;
const id_usuario = $('Edit Fields2').first().json.id_usuario;
const id_institucion = $('Edit Fields2').first().json.id_institucion;

// Procesar todos los items de entrada
const processedItems = items.map(item => {
  const {
    c1, c2, c3, c4, c5, c6,
    palabra_clave,
    ...rest
  } = item.json;

  return {
    ...rest,
    palabraClave: palabra_clave,
    criterios: {
      c1,
      c2,
      c3,
      c4,
      c5,
      c6
    },
    _processedAt: new Date().toISOString()
  };
});

// Retornar UN solo item agregado
return [
  {
    json: {
      nombre_materia,
      descripcion_general,
      competencias,
      temario,
      palabras_clave,
      id_usuario,
      id_institucion,
      items: processedItems
    }
  }
];

